"""Serialize directly authored catalog judgments; no semantic inference or model call."""
import json,gzip,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parents[1]
data=json.loads(gzip.decompress((R/'SOURCE.json.gz').read_bytes()));cat=json.loads((R/'CATALOG.json').read_text());order=json.loads((R/'ORDER.json').read_text())
def digest(v):return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
def witness(n,interpretation,path='en'):
 r=data['candidates'][order[n]];v=r['content']
 for k in path.split('/'):v=v[int(k)] if isinstance(v,list) else v[k]
 assert isinstance(v,str)
 return {'ordinal':n,'candidate_id':r['id'],'record_kind':r['record_kind'],'realization_id':'base','source_record_sha256':digest(r),'pointer':'/content/'+path,'quote':v,'direct_judgment':interpretation,'source_conditions':r['conditions'],'source_effects':r['effects'],'native_status':'Semantic witness only; this report does not create or certify native role evidence. Existing source effects/guards still require root review.'}
def change(slot,key,after):return {'pointer':'/slot_catalog/'+slot+'/'+key,'before':cat[slot][key],'after':after}
def proposal(pid,slot,reason,changes,pos,neg):return {'id':pid,'slot_id':slot,'status':'proposal_only_not_applied','general_definition':cat[slot]['description'],'spec_before_sha256':digest(cat[slot]),'reason':reason,'changes':changes,'positive_frozen_witnesses':pos,'negative_frozen_witnesses':neg,'preserve':['Exact owned positive source evidence, concrete property and selected realization.','All intrinsic candidate conditions, source/reference bindings, property locks, subject and actor counts, and requester exclusions.','Grounded existing required_carriers; carrier existence is not mutation permission.','Separate age and content-policy eligibility, including intrinsic adult guards; catalog changes do not authorize disallowed content.','No automatic role addition, source mutation, topic inference or blanket rehash of old native proof.']}
P=[]
P.append(proposal('P01','contact_point','The entity-owned definition includes object/material support and contact. Primary human-only eligibility and topic denies reject these endpoints even though their carrier is not a person. Remove only this semantic slot applicability; do not remove any source guard.',[change('contact_point','applicability',{})],[witness(10060,'Ship support within a dock basin is an owned nonhuman support relation; do not invent blocks or shipyard personnel.'),witness(10298,'Liquid is explicitly attached to a solid edge with a wet contact patch.'),witness(10409,'The source declares a source-to-receiver liquid connection; its explicit receiver contact is in the relation predicate.','relations/1/type')],[witness(10497,'The gap between nearby hands is not hand-to-hand contact. Their separate support facts may independently qualify; this is a negative only for the inter-hand contact claim.'),witness(10423,'Distant attenuation by haze does not identify a touching pair.')]))
P.append(proposal('P02','prop_placement','The definition owns object position relative to actors OR surfaces/boundaries, not exclusively human-primary scenes. Human-only and product/food/wildlife denies conflate a scene topic with the explicit prop carrier.',[change('prop_placement','applicability',{})],[witness(10196,'A sealed existing sample is beneath a named probe; retain punk_nanopunk prerequisite and do not add a new operator.'),witness(10417,'An explicitly declared workpiece or charge is inside the same chamber.'),witness(10344,'Separate metal object and folded cloth occupy different regions of an existing palm; a product/craft recording topic does not erase that placement.')],[witness(10452,'Hair or fur tip deformation is an anatomical surface structure, not a prop position.'),witness(10486,'The viscous-looking coating/runnel is a surface state; it does not itself establish a separately placed scene prop.')]))
P.append(proposal('P03','ambient_particle','An airborne droplet remains an airborne droplet in a product, jewelry or food recording. Topic exclusions do not express the particle ownership boundary. This change does not broaden airborne into underwater or unresolved optical media.',[change('ambient_particle','applicability',{})],[witness(10274,'Explicit airborne impact droplets form a coherent fan tied to a collision zone.'),witness(10400,'Explicit airborne rain streaks remain distinct from wet ground and ground impact.')],[witness(10133,'Suspended marine aggregates are underwater, outside this slot airborne boundary.'),witness(10187,'Gas pockets inside water are not airborne liquid droplets.')]))
P.append(proposal('P04','grain_profile','Image-plane grain/noise is medium/capture output rather than a property of the photograph topic. Product/jewelry/food denies exclude deliberately selected grain even while locked local material/color remains unchanged.',[change('grain_profile','applicability',{})],[witness(1000,'Fine film grain belongs to image_plane; source already has rendering.grain in style.'),witness(313,'Rough high-ISO film grain is semantically image grain; the source currently has material/empty properties and needs independent native correction before qualification.'),witness(1775,'Film or sensor grain is image-plane appearance; its composition/empty effects are not sufficient native property evidence until corrected.')],[witness(1122,'Paper grain belongs to the page material, not stochastic image grain.'),witness(1376,'Whiteout blizzard grain is ambiguous airborne snow language with weather prerequisites. Do not turn a keyword grain into film/sensor noise.')]))
P.append(proposal('P05','lens_artifact','The definition explicitly owns optical-path image effects. Product/jewelry/food/wildlife/craft are subjects or recording purposes, not proof that an authored veiling flare lacks optical meaning. Remove topic denies while keeping optical/scene/encoding separation.',[change('lens_artifact','applicability',{})],[witness(10376,'Veiling flare reduces captured-image contrast toward a bright source. The exact optical source semantics support lens_artifact; current optical.lens_artifact effects prefix requires separate root correction.','paraphrases/1'),witness(1917,'Veiling glare from backlight is a second optical-path witness. Empty source properties mean semantic evidence, not currently certified native qualification.')],[witness(10277,'Newton-ring interference is owned by a real lens/plate air-gap interface, not an artifact of the photographing camera optical path.'),witness(10423,'Actual environmental haze attenuation is a medium response, not optical-path flare.')]))
P.append(proposal('P06','garment_detail','Construction/topology is owned by an actual garment. A human wearer in a product, food-work or wildlife-work recording still has garment seams/coverage. Retain the current human category scope in this narrow proposal; removing all wearer-category restrictions would require further nonhuman/standalone garment witnesses.',[change('garment_detail','applicability',{'subject_categories':['human']})],[witness(10419,'A continuous seam connects upper/lower panels of the same worn bodice below the bust; garment construction is explicit.'),witness(10496,'One selected hand is enclosed by a glove whose own cuff terminates at the same wrist; opposite-hand coverage remains independent.')],[witness(10493,'A neck-wearable cord loop does not establish garment construction or actual wearing.'),witness(10142,'A scar-like line/patch belongs to skin, not a textile seam.')]))
P.append(proposal('P07','attire_context','Documentary and craft describe photographic purpose/practice and do not negate explicitly declared workwear or era-informed fitting. Remove only those two denied topics here; keep existing human scope and leave other topic denials for separate policy/evidence review rather than pretending all restrictions are resolved.',[change('attire_context','applicability',{'deny_domains':['wildlife','product','jewelry','food'],'subject_categories':['human']})],[witness(10076,'Workwear is explicitly named; reflective strips alone would not establish an occupation. A documentary recording can retain this declared attire context.'),witness(10146,'The source explicitly names rococo garment fitting and active alteration. A craft documentation context does not cancel that selected era-informed attire; retain punk_rococopunk prerequisite.')],[witness(10328,'Crossed straps and metal rings are physical construction; bondage-inspired lookup alone is not an actual selected fetish or cultural context.'),witness(10493,'A cork-shaped plug loop does not establish an era, culture, ceremony or occupation.')]))
P.append(proposal('P08','ambient_particle','Disambiguate observable units from an unresolved optical field. Fog can physically contain droplets while being described only by continuous attenuation; physical particulate composition alone is not positive evidence for distinct ambient particles.',[change('ambient_particle','description','Individually distinguishable airborne particles or droplets and their spatial distribution, separate from an unresolved haze or fog optical field.'),change('ambient_particle','description_ko','공기 중에서 개별 형상·점·궤적으로 구별되는 입자·물방울과 그 분포. 물리적으로 미립자를 포함하더라도 개별 입자 없이 연속 감쇠장으로만 표현된 안개·연무는 atmospheric_medium이며, 수중 입자·영상 입자·표면 방울과 구별한다.'),change('ambient_particle','excludes',['An unresolved haze or fog field described only through spatial attenuation or contrast loss.','Underwater particles or bubbles, image-plane grain and droplets attached to a surface.','A living airborne animal needs its own declared subject/participant evidence; the particle slot does not add one.'])],[witness(10274,'Airborne droplets and a fan describe distinguishable particle geometry.'),witness(10400,'Rain streak units at a selected exposure are explicit airborne particle rendering.')],[witness(10423,'Low suspended haze with distance contrast loss is an unresolved optical field; no individual droplet geometry is given.'),witness(10133,'Marine aggregates may be distinct particles but are not airborne.')]))
P.append(proposal('P09','atmospheric_medium','Clarify the existing English definition air/haze/fog as continuous or unresolved spatial optical response. Particle-free should mean no separately described particle units, not a scientific assertion that fog has no droplets. Keep scene medium distinct from camera-path flare.',[change('atmospheric_medium','description','Continuous or unresolved air, haze or fog and its spatial optical response, separate from individually distinguishable airborne particles, camera-path artifacts and emotional atmosphere.'),change('atmospheric_medium','description_ko','공기·안개·연무가 연속 또는 비분해 광학장으로 만드는 공간 감쇠·대비·가시성 상태. 안개의 물리적 미립자 유무를 사진으로 판정하지 않으며, 개별 공기 입자·물방울 형상은 ambient_particle, 촬영 광학 경로의 베일은 lens_artifact, 정서는 mood로 구별한다.'),change('atmospheric_medium','excludes',['Individually distinguishable airborne particle or droplet units alone.','Camera-path veiling flare, image-plane grain or encoding damage.','Emotional mood, an inferred weather cause, or unobserved chemical composition.'])],[witness(10423,'Near/far contrast and legibility vary through low haze: a direct spatial medium response.'),witness(10288,'Visible condensed mist near a bounded spring pool supplies a local unresolved medium; this does not require an actual temperature or mineral composition.')],[witness(10274,'Distinct impact droplets/fan alone do not establish a continuous medium attenuation field.'),witness(10376,'The luminous veil belongs to the captured camera path, not room air.','paraphrases/1')]))
